from marshmallow import validate, ValidationError

v = validate.Alphanumeric()

# Valid inputs
valid = ['abc123', 'Z']
for val in valid:
    try:
        result = v(val)
        print(f"✓ '{val}' is valid")
    except ValidationError as e:
        print(f"✗ '{val}' failed: {e}")

# Invalid inputs
invalid = ['a-b', '', 'héllo']
for val in invalid:
    try:
        result = v(val)
        print(f"✗ '{val}' should have failed but didn't")
    except ValidationError as e:
        print(f"✓ '{val}' correctly rejected")

# Test custom error message
v_custom = validate.Alphanumeric(error="'{input}' is not valid")
try:
    v_custom('a-b')
except ValidationError as e:
    print(f"\n✓ Custom error message works: {e.messages}")
EOF

