from marshmallow import validate, ValidationError

v = validate.EndsWith('.py')

# Valid inputs
test_cases_valid = ['main.py', '.py']
for test_input in test_cases_valid:
    try:
        result = v(test_input)
        print(f"✓ Valid: '{test_input}' → '{result}'")
    except ValidationError as e:
        print(f"✗ Invalid (should be valid): '{test_input}' → {e.messages}")

# Invalid inputs
test_cases_invalid = ['main.pyc', '']
for test_input in test_cases_invalid:
    try:
        result = v(test_input)
        print(f"✗ Valid (should be invalid): '{test_input}' → '{result}'")
    except ValidationError as e:
        print(f"✓ Invalid: '{test_input}' → {e.messages}")
